{"command":"cat <<'EOF' > src/main.rs
use clap::{Parser, ValueEnum};
use chrono::{Local, DateTime};
use std::process::{Command, Stdio, ExitStatus};
use std::io::{Read, Write, BufReader};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};
use serde::{Serialize, Deserialize};
use ratatui::{
    backend::CrosstermBackend,
    Terminal,
    widgets::{Block, Paragraph, Wrap, Borders, Clear},
    layout::{Layout, Constraint, Direction, Rect},
    style::{Style, Color, Modifier, Stylize},
    text::{Line, Span, Text},
};
use crossterm::{
    event::{self, Event, KeyCode, KeyEvent},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use similar::{ChangeTag, TextDiff};

#[derive(Parser, Debug, Clone)]
#[command(version, about)]
struct Args {
    #[arg(required = true)]
    command: Vec<String>,

    #[arg(short = 'b', long)]
    batch: bool,

    #[arg(short = 'B', long)]
    beep: bool,

    #[arg(long)]
    border: bool,

    #[arg(long)]
    with_scrollbar: bool,

    #[arg(long)]
    mouse: bool,

    #[arg(short = 'c', long)]
    color: bool,

    #[arg(short = 'r', long)]
    reverse: bool,

    #[arg(short = 'C', long)]
    compress: bool,

    #[arg(short = 't', long)]
    no_title: bool,

    #[arg(long)]
    enable_summary_char: bool,

    #[arg(short = 'N', long)]
    line_number: bool,

    #[arg(long)]
    no_help_banner: bool,

    #[arg(long)]
    no_summary: bool,

    #[arg(short = 'x', long)]
    exec: bool,

    #[arg(short = 'O', long)]
    diff_output_only: bool,

    #[arg(short = 'A', long)]
    aftercommand: Option<String>,

    #[arg(short = 'l', long)]
    logfile: Option<Option<String>>,

    #[arg(short = 's', long, default_value = "sh -c")]
    shell: String,

    #[arg(short = 'n', long, default_value_t = 2.0)]
    interval: f64,

    #[arg(long)]
    precise: bool,

    #[arg(short = 'L', long, default_value_t = 5000)]
    limit: usize,

    #[arg(long, default_value_t = 4)]
    tab_size: usize,

    #[arg(short = 'd', long, num_args = 0..=1, default_missing_value = "watch")]
    differences: Option<DiffMode>,

    #[arg(short = 'o', long, default_value = "output")]
    output: OutputMode,

    #[arg(short = 'K', long)]
    keymap: Vec<String>,
}

#[derive(ValueEnum, Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
enum DiffMode {
    None,
    Watch,
    Line,
    Word,
}

#[derive(ValueEnum, Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
enum OutputMode {
    Output,
    Stdout,
    Stderr,
}

#[derive(Clone, Serialize, Deserialize)]
struct ExecutionResult {
    timestamp: String,
    command: String,
    status: bool,
    output: String,
    stdout: String,
    stderr: String,
}

struct App {
    args: Args,
    history: Vec<ExecutionResult>,
    selected_history_index: usize,
    history_scroll: usize,
    watch_scroll: usize,
    focused_pane: FocusedPane,
    diff_mode: DiffMode,
    output_mode: OutputMode,
    show_title: bool,
    show_history: bool,
    show_line_number: bool,
    show_color: bool,
    reverse_display: bool,
    diff_output_only: bool,
    last_update: Instant,
    interval: Duration,
    should_quit: bool,
}

enum FocusedPane {
    Watch,
    History,
}

impl App {
    fn new(args: Args) -> Self {
        let interval = Duration::from_secs_f64(args.interval);
        let diff_mode = args.differences.clone().unwrap_or(DiffMode::None);
        let output_mode = args.output.clone();
        let show_title = !args.no_title;
        let show_line_number = args.line_number;
        let show_color = args.color;
        let reverse_display = args.reverse;
        let diff_output_only = args.diff_output_only;

        App {
            args,
            history: Vec::new(),
            selected_history_index: 0,
            history_scroll: 0,
            watch_scroll: 0,
            focused_pane: FocusedPane::Watch,
            diff_mode,
            output_mode,
            show_title,
            show_history: true,
            show_line_number,
            show_color,
            reverse_display,
            diff_output_only,
            last_update: Instant::now() - interval,
            interval,
            should_quit: false,
        }
    }

    fn run_command(&mut self) {
        let mut cmd;
        if self.args.exec {
            cmd = Command::new(&self.args.command[0]);
            cmd.args(&self.args.command[1..]);
        } else {
            let shell_parts: Vec<&str> = self.args.shell.split_whitespace().collect();
            cmd = Command::new(shell_parts[0]);
            for part in &shell_parts[1..] {
                cmd.arg(part);
            }
            cmd.arg(self.args.command.join(" "));
        }

        cmd.stdout(Stdio::piped());
        cmd.stderr(Stdio::piped());

        let start_time = Local::now();
        let mut child = match cmd.spawn() {
            Ok(c) => c,
            Err(e) => {
                // Handle error
                return;
            }
        };

        let stdout = child.stdout.take().unwrap();
        let stderr = child.stderr.take().unwrap();

        let output_combined = Arc::new(Mutex::new(String::new()));
        let stdout_str = Arc::new(Mutex::new(String::new()));
        let stderr_str = Arc::new(Mutex::new(String::new()));

        let out_c = output_combined.clone();
        let st_c = stdout_str.clone();
        let t1 = thread::spawn(move || {
            let mut reader = BufReader::new(stdout);
            let mut buf = [0; 1024];
            while let Ok(n) = reader.read(&mut buf) {
                if n == 0 { break; }
                let s = String::from_utf8_lossy(&buf[..n]);
                out_c.lock().unwrap().push_str(&s);
                st_c.lock().unwrap().push_str(&s);
            }
        });

        let out_c2 = output_combined.clone();
        let se_c = stderr_str.clone();
        let t2 = thread::spawn(move || {
            let mut reader = BufReader::new(stderr);
            let mut buf = [0; 1024];
            while let Ok(n) = reader.read(&mut buf) {
                if n == 0 { break; }
                let s = String::from_utf8_lossy(&buf[..n]);
                out_c2.lock().unwrap().push_str(&s);
                se_c.lock().unwrap().push_str(&s);
            }
        });

        let status = child.wait().map(|s| s.success()).unwrap_or(false);
        t1.join().unwrap();
        t2.join().unwrap();

        let result = ExecutionResult {
            timestamp: start_time.format("%Y-%m-%d %H:%M:%S%.3f").to_string(),
            command: self.args.command.join(" "),
            status,
            output: output_combined.lock().unwrap().clone(),
            stdout: stdout_str.lock().unwrap().clone(),
            stderr: stderr_str.lock().unwrap().clone(),
        };

        let changed = self.history.is_empty() || self.history[0].output != result.output || self.history[0].status != result.status;

        if changed {
            // Check aftercommand
            if let Some(after_cmd) = &self.args.aftercommand {
                let data = serde_json::json!({
                    "before_result": if self.history.is_empty() { serde_json::json!({
                        "timestamp": "",
                        "command": "",
                        "status": true,
                        "output": "",
                        "stdout": "",
                        "stderr": ""
                    }) } else { serde_json::to_value(&self.history[0]).unwrap() },
                    "after_result": serde_json::to_value(&result).unwrap()
                });

                let mut after_process = Command::new("sh")
                    .arg("-c")
                    .arg(after_cmd)
                    .env("HWATCH_DATA", serde_json::to_string(&data).unwrap())
                    .spawn()
                    .ok();
            }

            // Logging
            if let Some(logfile_opt) = &self.args.logfile {
                if let Some(logfile) = logfile_opt {
                    if let Ok(mut file) = std::fs::OpenOptions::new().create(true).append(true).open(logfile) {
                        if self.history.is_empty() {
                            let initial = serde_json::json!({
                                "timestamp": "",
                                "command": "",
                                "status": true,
                                "output": "",
                                "stdout": "",
                                "stderr": ""
                            });
                            let _ = writeln!(file, "{}", serde_json::to_string(&initial).unwrap());
                        }
                        let _ = writeln!(file, "{}", serde_json::to_string(&result).unwrap());
                    }
                }
            }

            if self.args.beep {
                print!("\x07");
                let _ = std::io::stdout().flush();
            }
        }

        self.history.insert(0, result);
        if self.args.limit > 0 && self.history.len() > self.args.limit {
            self.history.truncate(self.args.limit);
        }

        if self.selected_history_index != 0 {
             self.selected_history_index += 1;
             if self.selected_history_index >= self.history.len() {
                 self.selected_history_index = self.history.len() - 1;
             }
        }
    }

    fn toggle_diff_mode(&mut self) {
        self.diff_mode = match self.diff_mode {
            DiffMode::None => DiffMode::Watch,
            DiffMode::Watch => DiffMode::Line,
            DiffMode::Line => DiffMode::Word,
            DiffMode::Word => DiffMode::None,
        };
    }

    fn set_diff_mode(&mut self, mode: DiffMode) {
        self.diff_mode = mode;
    }

    fn toggle_output_mode(&mut self) {
        self.output_mode = match self.output_mode {
            OutputMode::Output => OutputMode::Stdout,
            OutputMode::Stdout => OutputMode::Stderr,
            OutputMode::Stderr => OutputMode::Output,
        };
    }

    fn set_output_mode(&mut self, mode: OutputMode) {
        self.output_mode = mode;
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    if args.batch {
        run_batch(args)?;
        return Ok(());
    }

    enable_raw_mode()?;
    let mut stdout = std::io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new(args);

    loop {
        if Instant::now().duration_since(app.last_update) >= app.interval {
            app.run_command();
            app.last_update = Instant::now();
        }

        terminal.draw(|f| ui(f, &mut app))?;

        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if handle_keys(key, &mut app) {
                    break;
                }
            }
        }
        if app.should_quit {
            break;
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}

fn run_batch(args: Args) -> Result<(), Box<dyn std::error::Error>> {
    let mut app = App::new(args.clone());
    loop {
        app.run_command();
        let result = &app.history[0];

        // Header
        print!("\x1b[38;5;240m=====[{}]=========================\x1b[0m\n", result.timestamp);

        let output = match app.output_mode {
            OutputMode::Output => &result.output,
            OutputMode::Stdout => &result.stdout,
            OutputMode::Stderr => &result.stderr,
        };
        print!("{}", output);
        if !output.ends_with('\n') {
            println!();
        }
        println!();

        thread::sleep(app.interval);
    }
}

fn handle_keys(key: KeyEvent, app: &mut App) -> bool {
    match key.code {
        KeyCode::Char('q') => return true,
        KeyCode::Char('c') => app.show_color = !app.show_color,
        KeyCode::Char('n') => app.show_line_number = !app.show_line_number,
        KeyCode::Char('r') => app.reverse_display = !app.reverse_display,
        KeyCode::Char('d') => app.toggle_diff_mode(),
        KeyCode::Char('o') => app.toggle_output_mode(),
        KeyCode::Char('t') => {
            app.show_title = !app.show_title;
            app.show_history = app.show_title;
        }
        KeyCode::Backspace => app.show_history = !app.show_history,
        KeyCode::Char('0') => app.set_diff_mode(DiffMode::None),
        KeyCode::Char('1') => app.set_diff_mode(DiffMode::Watch),
        KeyCode::Char('2') => app.set_diff_mode(DiffMode::Line),
        KeyCode::Char('3') => app.set_diff_mode(DiffMode::Word),
        KeyCode::F(1) => app.set_output_mode(OutputMode::Stdout),
        KeyCode::F(2) => app.set_output_mode(OutputMode::Stderr),
        KeyCode::F(3) => app.set_output_mode(OutputMode::Output),
        KeyCode::Tab => {
            app.focused_pane = match app.focused_pane {
                FocusedPane::Watch => FocusedPane::History,
                FocusedPane::History => FocusedPane::Watch,
            };
        }
        KeyCode::Up => {
            match app.focused_pane {
                FocusedPane::Watch => {
                    if app.watch_scroll > 0 { app.watch_scroll -= 1; }
                }
                FocusedPane::History => {
                    if app.selected_history_index > 0 {
                        app.selected_history_index -= 1;
                    }
                }
            }
        }
        KeyCode::Down => {
            match app.focused_pane {
                FocusedPane::Watch => {
                    app.watch_scroll += 1;
                }
                FocusedPane::History => {
                    if app.selected_history_index < app.history.len() - 1 {
                        app.selected_history_index += 1;
                    }
                }
            }
        }
        KeyCode::Char('+') => {
            app.interval += Duration::from_millis(500);
        }
        KeyCode::Char('-') => {
            if app.interval > Duration::from_millis(500) {
                app.interval -= Duration::from_millis(500);
            }
        }
        _ => {}
    }
    false
}

fn ui(f: &mut ratatui::Frame, app: &mut App) {
    let mut main_constraints = vec![];
    if app.show_title {
        main_constraints.push(Constraint::Length(1));
        main_constraints.push(Constraint::Length(1));
    }
    main_constraints.push(Constraint::Min(0));

    let main_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints(main_constraints)
        .split(f.size());

    let mut current_idx = 0;
    if app.show_title {
        let top_line = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([
                Constraint::Percentage(40),
                Constraint::Percentage(20),
                Constraint::Percentage(40),
            ])
            .split(main_chunks[current_idx]);

        let interval_str = format!("{:>9.3}", app.interval.as_secs_f64());
        let cmd_str = app.args.command.join(" ");
        let header_left = Line::from(vec![
            Span::raw("Every "),
            Span::styled(interval_str, Style::default().fg(Color::Cyan)),
            Span::raw(":"),
            Span::styled(cmd_str, Style::default().fg(Color::Green)),
        ]);
        f.render_widget(Paragraph::new(header_left), top_line[0]);

        if !app.args.no_help_banner {
            let help_banner = Span::styled("Display help with h key!", Style::default().add_modifier(Modifier::REVERSED));
            f.render_widget(Paragraph::new(Line::from(help_banner)).alignment(ratatui::layout::Alignment::Center), top_line[1]);
        }

        let timestamp = if !app.history.is_empty() { &app.history[0].timestamp } else { "" };
        let header_right = Line::from(Span::styled(timestamp, Style::default().fg(Color::Cyan)));
        f.render_widget(Paragraph::new(header_right).alignment(ratatui::layout::Alignment::Right), top_line[2]);

        current_idx += 1;

        // Second line: indicators
        let indicators = vec![
            format_indicator("Number", app.show_line_number, Color::Green),
            format_indicator("Color", app.show_color, Color::Green),
            format_indicator("Reverse", app.reverse_display, Color::Green),
            format_indicator_value("Output", &format!("{:?}", app.output_mode), Color::Yellow),
            format_indicator_value(
                match app.focused_pane { FocusedPane::History => "History", FocusedPane::Watch => "Watch" },
                match app.focused_pane { FocusedPane::History => "History", FocusedPane::Watch => "Watch" },
                Color::Cyan
            ),
            format_indicator_value("Diff", &format!("{:<10?}", app.diff_mode), Color::Magenta),
        ];

        let mut spans = vec![Span::raw("                     ")];
        for (i, span) in indicators.into_iter().enumerate() {
            if i > 0 { spans.push(Span::raw(" ")); }
            spans.push(Span::raw("["));
            spans.push(span);
            spans.push(Span::raw("]"));
        }
        f.render_widget(Paragraph::new(Line::from(spans)), main_chunks[current_idx]);
        current_idx += 1;
    }

    let body_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints(if app.show_history {
            [Constraint::Min(0), Constraint::Length(30)]
        } else {
            [Constraint::Min(0), Constraint::Length(0)]
        })
        .split(main_chunks[current_idx]);

    // Watch pane
    let content = if app.history.is_empty() {
        Text::raw("")
    } else {
        let current_res = &app.history[app.selected_history_index];
        let text = match app.output_mode {
            OutputMode::Output => &current_res.output,
            OutputMode::Stdout => &current_res.stdout,
            OutputMode::Stderr => &current_res.stderr,
        };

        match app.diff_mode {
            DiffMode::None => {
                format_content(text, app.show_line_number, app.show_color)
            }
            DiffMode::Watch => {
                if app.selected_history_index + 1 < app.history.len() {
                    let prev_res = &app.history[app.selected_history_index + 1];
                    let prev_text = match app.output_mode {
                        OutputMode::Output => &prev_res.output,
                        OutputMode::Stdout => &prev_res.stdout,
                        OutputMode::Stderr => &prev_res.stderr,
                    };
                    format_watch_diff(text, prev_text, app.show_line_number)
                } else {
                    format_content(text, app.show_line_number, app.show_color)
                }
            }
            DiffMode::Line => {
                 if app.selected_history_index + 1 < app.history.len() {
                    let prev_res = &app.history[app.selected_history_index + 1];
                    let prev_text = match app.output_mode {
                        OutputMode::Output => &prev_res.output,
                        OutputMode::Stdout => &prev_res.stdout,
                        OutputMode::Stderr => &prev_res.stderr,
                    };
                    format_line_diff(text, prev_text, app.show_line_number, app.diff_output_only)
                } else {
                    format_content(text, app.show_line_number, app.show_color)
                }
            }
            DiffMode::Word => {
                if app.selected_history_index + 1 < app.history.len() {
                    let prev_res = &app.history[app.selected_history_index + 1];
                    let prev_text = match app.output_mode {
                        OutputMode::Output => &prev_res.output,
                        OutputMode::Stdout => &prev_res.stdout,
                        OutputMode::Stderr => &prev_res.stderr,
                    };
                    format_word_diff(text, prev_text, app.show_line_number, app.diff_output_only)
                } else {
                    format_content(text, app.show_line_number, app.show_color)
                }
            }
        }
    };

    let mut paragraph = Paragraph::new(content);
    if app.reverse_display {
        // paragraph = paragraph.wrap(Wrap { trim: false }); // Should we wrap?
    }
    f.render_widget(paragraph, body_chunks[0]);

    // History pane
    if app.show_history {
        let history_items: Vec<Line> = app.history.iter().enumerate().map(|(i, res)| {
            let style = if i == app.selected_history_index {
                Style::default().fg(Color::White).bg(Color::Rgb(64, 64, 64)).add_modifier(Modifier::BOLD)
            } else {
                Style::default().fg(Color::Green)
            };
            let prefix = if i == app.selected_history_index { ">>" } else { "  " };
            let label = if i == 0 { "latest" } else { "" };
            Line::from(vec![
                Span::styled(format!("{}{}", prefix, label), style),
                Span::styled(format!("\n  {}", res.timestamp), style),
            ])
        }).collect();

        let mut history_text = Text::default();
        for (i, res) in app.history.iter().enumerate() {
            let is_selected = i == app.selected_history_index;
            let timestamp_style = Style::default().fg(Color::Green);
            let selected_style = Style::default().fg(Color::White).bg(Color::Blue).add_modifier(Modifier::BOLD);

            if i == 0 {
                let mut latest_span = Span::styled(">>latest", if is_selected { selected_style } else { Style::default().fg(Color::White).bg(Color::Indexed(8)).add_modifier(Modifier::BOLD) });
                history_text.lines.push(Line::from(latest_span));
            } else {
                if is_selected {
                   history_text.lines.push(Line::from(Span::styled(format!(">>{}", res.timestamp), selected_style)));
                   continue;
                }
            }
            history_text.lines.push(Line::from(Span::styled(format!("  {}", res.timestamp), timestamp_style)));
        }

        f.render_widget(Paragraph::new(history_text), body_chunks[1]);
    }
}

fn format_indicator(label: &str, active: bool, color: Color) -> Span<'static> {
    if active {
        Span::styled(label.to_string(), Style::default().fg(color).add_modifier(Modifier::REVERSED | Modifier::BOLD))
    } else {
        Span::styled(label.to_string(), Style::default().fg(Color::Indexed(7)))
    }
}

fn format_indicator_value(label: &str, value: &str, color: Color) -> Span<'static> {
    Span::styled(value.to_string(), Style::default().fg(color).add_modifier(Modifier::REVERSED))
}

fn format_content(text: &str, show_line_number: bool, show_color: bool) -> Text<'static> {
    let mut lines = vec![];
    for (i, line) in text.lines().enumerate() {
        let mut spans = vec![];
        if show_line_number {
            spans.push(Span::styled(format!("{:>3} | ", i + 1), Style::default().fg(Color::Indexed(8))));
        }
        spans.push(Span::raw(line.to_string()));
        lines.push(Line::from(spans));
    }
    Text::from(lines)
}

fn format_watch_diff(text: &str, prev_text: &str, show_line_number: bool) -> Text<'static> {
    let mut lines = vec![];
    let prev_chars: Vec<char> = prev_text.chars().collect();
    let curr_chars: Vec<char> = text.chars().collect();

    let mut char_idx = 0;
    for (i, line_str) in text.lines().enumerate() {
        let mut spans = vec![];
        if show_line_number {
            spans.push(Span::styled(format!("{:>3} | ", i + 1), Style::default().fg(Color::Indexed(8))));
        }

        for c in line_str.chars() {
            let style = if char_idx < prev_chars.len() && c == prev_chars[char_idx] {
                Style::default()
            } else {
                Style::default().add_modifier(Modifier::REVERSED)
            };
            spans.push(Span::styled(c.to_string(), style));
            char_idx += 1;
        }
        char_idx += 1; // for newline
        lines.push(Line::from(spans));
    }
    Text::from(lines)
}

fn format_line_diff(text: &str, prev_text: &str, show_line_number: bool, diff_only: bool) -> Text<'static> {
    let mut lines = vec![];
    let diff = TextDiff::from_lines(prev_text, text);
    let mut line_num = 1;
    for change in diff.iter_all_changes() {
        match change.tag() {
            ChangeTag::Delete => {
                if !diff_only {
                    let mut spans = vec![];
                    if show_line_number { spans.push(Span::raw("    | ")); }
                    spans.push(Span::styled(format!("-{}", change.value()), Style::default().fg(Color::Red)));
                    lines.push(Line::from(spans));
                }
            }
            ChangeTag::Insert => {
                let mut spans = vec![];
                if show_line_number {
                    spans.push(Span::styled(format!("{:>3} | ", line_num), Style::default().fg(Color::Indexed(8))));
                    line_num += 1;
                }
                spans.push(Span::styled(format!("+{}", change.value()), Style::default().fg(Color::Green)));
                lines.push(Line::from(spans));
            }
            ChangeTag::Equal => {
                if !diff_only {
                    let mut spans = vec![];
                    if show_line_number {
                        spans.push(Span::styled(format!("{:>3} | ", line_num), Style::default().fg(Color::Indexed(8))));
                        line_num += 1;
                    }
                    spans.push(Span::raw(format!(" {}", change.value())));
                    lines.push(Line::from(spans));
                } else {
                    line_num += 1;
                }
            }
        }
    }
    Text::from(lines)
}

fn format_word_diff(text: &str, prev_text: &str, show_line_number: bool, diff_only: bool) -> Text<'static> {
    // Simplified word diff
    format_line_diff(text, prev_text, show_line_number, diff_only)
}
EOF
