                    format_watch_diff(text, prev_text, app.show_line_number)
                } else {
                    format_content(text, app.show_line_number, app.show_color)
                }
            }
            DiffMode::Line => {
                 if app.selected_history_index + 1 < app.history.len() {
                    let prev_res = &app.history[app.selected_history_index + 1];
                    let prev_text = match app.output_mode {
                        OutputMode::Output => &prev_res.output,
