#[derive(Clone, Serialize, Deserialize)]
struct ExecutionResult {
    timestamp: String,
    command: String,
    status: bool,
    output: String,
    stdout: String,
    stderr: String,
}

struct App {
    args: Args,
    history: Vec<ExecutionResult>,
    selected_history_index: usize,
    history_scroll: usize,
    watch_scroll: usize,
    focused_pane: FocusedPane,
    diff_mode: DiffMode,
    output_mode: OutputMode,
