    show_history: bool,
    show_line_number: bool,
    show_color: bool,
    reverse_display: bool,
    diff_output_only: bool,
    last_update: Instant,
    interval: Duration,
    should_quit: bool,
}

enum FocusedPane {
    Watch,
    History,
}

impl App {
    fn new(args: Args) -> Self {
        let interval = Duration::from_secs_f64(args.interval);
        let diff_mode = args.differences.clone().unwrap_or(DiffMode::None);
        let output_mode = args.output.clone();
        let show_title = !args.no_title;
        let show_line_number = args.line_number;
        let show_color = args.color;
        let reverse_display = args.reverse;
        let diff_output_only = args.diff_output_only;

        App {
            args,
            history: Vec::new(),
            selected_history_index: 0,
            history_scroll: 0,
            watch_scroll: 0,
            focused_pane: FocusedPane::Watch,
            diff_mode,
            output_mode,
            show_title,
            show_history: true,
            show_line_number,
            show_color,
            reverse_display,
            diff_output_only,
            last_update: Instant::now() - interval,
            interval,
            should_quit: false,
        }
    }

    fn run_command(&mut self) {
        let mut cmd;
        if self.args.exec {
            cmd = Command::new(&self.args.command[0]);
            cmd.args(&self.args.command[1..]);
        } else {
            let shell_parts: Vec<&str> = self.args.shell.split_whitespace().collect();
            cmd = Command::new(shell_parts[0]);
            for part in &shell_parts[1..] {
                cmd.arg(part);
            }
            cmd.arg(self.args.command.join(" "));
        }

        cmd.stdout(Stdio::piped());
        cmd.stderr(Stdio::piped());

        let start_time = Local::now();
        let mut child = match cmd.spawn() {
            Ok(c) => c,
            Err(e) => {
                // Handle error
                return;
            }
        };

        let stdout = child.stdout.take().unwrap();
        let stderr = child.stderr.take().unwrap();

        let output_combined = Arc::new(Mutex::new(String::new()));
        let stdout_str = Arc::new(Mutex::new(String::new()));
        let stderr_str = Arc::new(Mutex::new(String::new()));

        let out_c = output_combined.clone();
        let st_c = stdout_str.clone();
        let t1 = thread::spawn(move || {
            let mut reader = BufReader::new(stdout);
            let mut buf = [0; 1024];
            while let Ok(n) = reader.read(&mut buf) {
                if n == 0 { break; }
                let s = String::from_utf8_lossy(&buf[..n]);
                out_c.lock().unwrap().push_str(&s);
                st_c.lock().unwrap().push_str(&s);
            }
        });

        let out_c2 = output_combined.clone();
        let se_c = stderr_str.clone();
        let t2 = thread::spawn(move || {
            let mut reader = BufReader::new(stderr);
            let mut buf = [0; 1024];
            while let Ok(n) = reader.read(&mut buf) {
                if n == 0 { break; }
                let s = String::from_utf8_lossy(&buf[..n]);
                out_c2.lock().unwrap().push_str(&s);
                se_c.lock().unwrap().push_str(&s);
            }
        });

        let status = child.wait().map(|s| s.success()).unwrap_or(false);
        t1.join().unwrap();
        t2.join().unwrap();

        let result = ExecutionResult {
            timestamp: start_time.format("%Y-%m-%d %H:%M:%S%.3f").to_string(),
            command: self.args.command.join(" "),
            status,
            output: output_combined.lock().unwrap().clone(),
            stdout: stdout_str.lock().unwrap().clone(),
            stderr: stderr_str.lock().unwrap().clone(),
        };

        let changed = self.history.is_empty() || self.history[0].output != result.output || self.history[0].status != result.status;

        if changed {
            // Check aftercommand
            if let Some(after_cmd) = &self.args.aftercommand {
                let data = serde_json::json!({
                    "before_result": if self.history.is_empty() { serde_json::json!({
                        "timestamp": "",
                        "command": "",
                        "status": true,
                        "output": "",
                        "stdout": "",
                        "stderr": ""
                    }) } else { serde_json::to_value(&self.history[0]).unwrap() },
                    "after_result": serde_json::to_value(&result).unwrap()
                });

                let mut after_process = Command::new("sh")
                    .arg("-c")
                    .arg(after_cmd)
                    .env("HWATCH_DATA", serde_json::to_string(&data).unwrap())
                    .spawn()
                    .ok();
            }

            // Logging
            if let Some(logfile_opt) = &self.args.logfile {
                if let Some(logfile) = logfile_opt {
                    if let Ok(mut file) = std::fs::OpenOptions::new().create(true).append(true).open(logfile) {
                        if self.history.is_empty() {
                            let initial = serde_json::json!({
                                "timestamp": "",
                                "command": "",
                                "status": true,
                                "output": "",
                                "stdout": "",
                                "stderr": ""
                            });
