        }

        self.history.insert(0, result);
        if self.args.limit > 0 && self.history.len() > self.args.limit {
            self.history.truncate(self.args.limit);
        }

        if self.selected_history_index != 0 {
             self.selected_history_index += 1;
             if self.selected_history_index >= self.history.len() {
                 self.selected_history_index = self.history.len() - 1;
             }
        }
    }

    fn toggle_diff_mode(&mut self) {
        self.diff_mode = match self.diff_mode {
            DiffMode::None => DiffMode::Watch,
            DiffMode::Watch => DiffMode::Line,
            DiffMode::Line => DiffMode::Word,
            DiffMode::Word => DiffMode::None,
        };
    }

    fn set_diff_mode(&mut self, mode: DiffMode) {
        self.diff_mode = mode;
    }

    fn toggle_output_mode(&mut self) {
        self.output_mode = match self.output_mode {
            OutputMode::Output => OutputMode::Stdout,
            OutputMode::Stdout => OutputMode::Stderr,
            OutputMode::Stderr => OutputMode::Output,
        };
    }

    fn set_output_mode(&mut self, mode: OutputMode) {
        self.output_mode = mode;
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    if args.batch {
