            }
        }
        if app.should_quit {
            break;
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}

fn run_batch(args: Args) -> Result<(), Box<dyn std::error::Error>> {
    let mut app = App::new(args.clone());
    loop {
        app.run_command();
        let result = &app.history[0];

        // Header
        print!("\x1b[38;5;240m=====[{}]=========================\x1b[0m\n", result.timestamp);

        let output = match app.output_mode {
            OutputMode::Output => &result.output,
            OutputMode::Stdout => &result.stdout,
            OutputMode::Stderr => &result.stderr,
        };
        print!("{}", output);
        if !output.ends_with('\n') {
            println!();
        }
        println!();

        thread::sleep(app.interval);
    }
}

fn handle_keys(key: KeyEvent, app: &mut App) -> bool {
    match key.code {
        KeyCode::Char('q') => return true,
        KeyCode::Char('c') => app.show_color = !app.show_color,
        KeyCode::Char('n') => app.show_line_number = !app.show_line_number,
        KeyCode::Char('r') => app.reverse_display = !app.reverse_display,
        KeyCode::Char('d') => app.toggle_diff_mode(),
        KeyCode::Char('o') => app.toggle_output_mode(),
