        KeyCode::Backspace => app.show_history = !app.show_history,
        KeyCode::Char('0') => app.set_diff_mode(DiffMode::None),
        KeyCode::Char('1') => app.set_diff_mode(DiffMode::Watch),
        KeyCode::Char('2') => app.set_diff_mode(DiffMode::Line),
        KeyCode::Char('3') => app.set_diff_mode(DiffMode::Word),
        KeyCode::F(1) => app.set_output_mode(OutputMode::Stdout),
        KeyCode::F(2) => app.set_output_mode(OutputMode::Stderr),
        KeyCode::F(3) => app.set_output_mode(OutputMode::Output),
        KeyCode::Tab => {
            app.focused_pane = match app.focused_pane {
                FocusedPane::Watch => FocusedPane::History,
                FocusedPane::History => FocusedPane::Watch,
            };
        }
        KeyCode::Up => {
            match app.focused_pane {
                FocusedPane::Watch => {
                    if app.watch_scroll > 0 { app.watch_scroll -= 1; }
                }
                FocusedPane::History => {
                    if app.selected_history_index > 0 {
                        app.selected_history_index -= 1;
                    }
                }
            }
        }
        KeyCode::Down => {
            match app.focused_pane {
                FocusedPane::Watch => {
                    app.watch_scroll += 1;
                }
                FocusedPane::History => {
                    if app.selected_history_index < app.history.len() - 1 {
                        app.selected_history_index += 1;
                    }
                }
            }
        }
        KeyCode::Char('+') => {
            app.interval += Duration::from_millis(500);
        }
        KeyCode::Char('-') => {
            if app.interval > Duration::from_millis(500) {
                app.interval -= Duration::from_millis(500);
            }
        }
        _ => {}
    }
    false
}

fn ui(f: &mut ratatui::Frame, app: &mut App) {
    let mut main_constraints = vec![];
    if app.show_title {
        main_constraints.push(Constraint::Length(1));
        main_constraints.push(Constraint::Length(1));
    }
    main_constraints.push(Constraint::Min(0));

    let main_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints(main_constraints)
        .split(f.size());

    let mut current_idx = 0;
    if app.show_title {
        let top_line = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([
                Constraint::Percentage(40),
                Constraint::Percentage(20),
                Constraint::Percentage(40),
            ])
            .split(main_chunks[current_idx]);

        let interval_str = format!("{:>9.3}", app.interval.as_secs_f64());
        let cmd_str = app.args.command.join(" ");
        let header_left = Line::from(vec![
            Span::raw("Every "),
            Span::styled(interval_str, Style::default().fg(Color::Cyan)),
            Span::raw(":"),
            Span::styled(cmd_str, Style::default().fg(Color::Green)),
        ]);
        f.render_widget(Paragraph::new(header_left), top_line[0]);

        if !app.args.no_help_banner {
            let help_banner = Span::styled("Display help with h key!", Style::default().add_modifier(Modifier::REVERSED));
            f.render_widget(Paragraph::new(Line::from(help_banner)).alignment(ratatui::layout::Alignment::Center), top_line[1]);
        }

        let timestamp = if !app.history.is_empty() { &app.history[0].timestamp } else { "" };
        let header_right = Line::from(Span::styled(timestamp, Style::default().fg(Color::Cyan)));
        f.render_widget(Paragraph::new(header_right).alignment(ratatui::layout::Alignment::Right), top_line[2]);

        current_idx += 1;

        // Second line: indicators
        let indicators = vec![
            format_indicator("Number", app.show_line_number, Color::Green),
            format_indicator("Color", app.show_color, Color::Green),
            format_indicator("Reverse", app.reverse_display, Color::Green),
            format_indicator_value("Output", &format!("{:?}", app.output_mode), Color::Yellow),
            format_indicator_value(
                match app.focused_pane { FocusedPane::History => "History", FocusedPane::Watch => "Watch" },
                match app.focused_pane { FocusedPane::History => "History", FocusedPane::Watch => "Watch" },
                Color::Cyan
            ),
            format_indicator_value("Diff", &format!("{:<10?}", app.diff_mode), Color::Magenta),
        ];

        let mut spans = vec![Span::raw("                     ")];
        for (i, span) in indicators.into_iter().enumerate() {
            if i > 0 { spans.push(Span::raw(" ")); }
            spans.push(Span::raw("["));
            spans.push(span);
            spans.push(Span::raw("]"));
        }
        f.render_widget(Paragraph::new(Line::from(spans)), main_chunks[current_idx]);
        current_idx += 1;
    }

    let body_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints(if app.show_history {
            [Constraint::Min(0), Constraint::Length(30)]
        } else {
            [Constraint::Min(0), Constraint::Length(0)]
        })
        .split(main_chunks[current_idx]);

    // Watch pane
    let content = if app.history.is_empty() {
        Text::raw("")
    } else {
        let current_res = &app.history[app.selected_history_index];
        let text = match app.output_mode {
            OutputMode::Output => &current_res.output,
            OutputMode::Stdout => &current_res.stdout,
            OutputMode::Stderr => &current_res.stderr,
        };

        match app.diff_mode {
            DiffMode::None => {
                format_content(text, app.show_line_number, app.show_color)
            }
            DiffMode::Watch => {
                if app.selected_history_index + 1 < app.history.len() {
                    let prev_res = &app.history[app.selected_history_index + 1];
                    let prev_text = match app.output_mode {
                        OutputMode::Output => &prev_res.output,
                        OutputMode::Stdout => &prev_res.stdout,
                        OutputMode::Stderr => &prev_res.stderr,
                    };
                    format_watch_diff(text, prev_text, app.show_line_number)
                } else {
                    format_content(text, app.show_line_number, app.show_color)
                }
            }
            DiffMode::Line => {
                 if app.selected_history_index + 1 < app.history.len() {
                    let prev_res = &app.history[app.selected_history_index + 1];
                    let prev_text = match app.output_mode {
                        OutputMode::Output => &prev_res.output,
                        OutputMode::Stdout => &prev_res.stdout,
                        OutputMode::Stderr => &prev_res.stderr,
                    };
                    format_line_diff(text, prev_text, app.show_line_number, app.diff_output_only)
                } else {
                    format_content(text, app.show_line_number, app.show_color)
                }
            }
            DiffMode::Word => {
                if app.selected_history_index + 1 < app.history.len() {
                    let prev_res = &app.history[app.selected_history_index + 1];
                    let prev_text = match app.output_mode {
                        OutputMode::Output => &prev_res.output,
                        OutputMode::Stdout => &prev_res.stdout,
                        OutputMode::Stderr => &prev_res.stderr,
                    };
                    format_word_diff(text, prev_text, app.show_line_number, app.diff_output_only)
                } else {
                    format_content(text, app.show_line_number, app.show_color)
                }
            }
        }
    };

    let mut paragraph = Paragraph::new(content);
    if app.reverse_display {
        // paragraph = paragraph.wrap(Wrap { trim: false }); // Should we wrap?
    }
    f.render_widget(paragraph, body_chunks[0]);

    // History pane
    if app.show_history {
        let history_items: Vec<Line> = app.history.iter().enumerate().map(|(i, res)| {
            let style = if i == app.selected_history_index {
                Style::default().fg(Color::White).bg(Color::Rgb(64, 64, 64)).add_modifier(Modifier::BOLD)
            } else {
                Style::default().fg(Color::Green)
            };
            let prefix = if i == app.selected_history_index { ">>" } else { "  " };
            let label = if i == 0 { "latest" } else { "" };
            Line::from(vec![
                Span::styled(format!("{}{}", prefix, label), style),
                Span::styled(format!("\n  {}", res.timestamp), style),
            ])
        }).collect();

        let mut history_text = Text::default();
        for (i, res) in app.history.iter().enumerate() {
            let is_selected = i == app.selected_history_index;
            let timestamp_style = Style::default().fg(Color::Green);
            let selected_style = Style::default().fg(Color::White).bg(Color::Blue).add_modifier(Modifier::BOLD);

            if i == 0 {
                let mut latest_span = Span::styled(">>latest", if is_selected { selected_style } else { Style::default().fg(Color::White).bg(Color::Indexed(8)).add_modifier(Modifier::BOLD) });
                history_text.lines.push(Line::from(latest_span));
            } else {
                if is_selected {
                   history_text.lines.push(Line::from(Span::styled(format!(">>{}", res.timestamp), selected_style)));
                   continue;
                }
            }
            history_text.lines.push(Line::from(Span::styled(format!("  {}", res.timestamp), timestamp_style)));
        }

        f.render_widget(Paragraph::new(history_text), body_chunks[1]);
    }
}

fn format_indicator(label: &str, active: bool, color: Color) -> Span<'static> {
    if active {
        Span::styled(label.to_string(), Style::default().fg(color).add_modifier(Modifier::REVERSED | Modifier::BOLD))
    } else {
        Span::styled(label.to_string(), Style::default().fg(Color::Indexed(7)))
    }
}

fn format_indicator_value(label: &str, value: &str, color: Color) -> Span<'static> {
    Span::styled(value.to_string(), Style::default().fg(color).add_modifier(Modifier::REVERSED))
}

fn format_content(text: &str, show_line_number: bool, show_color: bool) -> Text<'static> {
    let mut lines = vec![];
    for (i, line) in text.lines().enumerate() {
        let mut spans = vec![];
        if show_line_number {
            spans.push(Span::styled(format!("{:>3} | ", i + 1), Style::default().fg(Color::Indexed(8))));
        }
        spans.push(Span::raw(line.to_string()));
        lines.push(Line::from(spans));
    }
    Text::from(lines)
}

fn format_watch_diff(text: &str, prev_text: &str, show_line_number: bool) -> Text<'static> {
    let mut lines = vec![];
    let prev_chars: Vec<char> = prev_text.chars().collect();
    let curr_chars: Vec<char> = text.chars().collect();

    let mut char_idx = 0;
    for (i, line_str) in text.lines().enumerate() {
        let mut spans = vec![];
        if show_line_number {
            spans.push(Span::styled(format!("{:>3} | ", i + 1), Style::default().fg(Color::Indexed(8))));
        }

        for c in line_str.chars() {
            let style = if char_idx < prev_chars.len() && c == prev_chars[char_idx] {
                Style::default()
            } else {
                Style::default().add_modifier(Modifier::REVERSED)
            };
            spans.push(Span::styled(c.to_string(), style));
            char_idx += 1;
        }
        char_idx += 1; // for newline
        lines.push(Line::from(spans));
    }
    Text::from(lines)
}

fn format_line_diff(text: &str, prev_text: &str, show_line_number: bool, diff_only: bool) -> Text<'static> {
    let mut lines = vec![];
    let diff = TextDiff::from_lines(prev_text, text);
    let mut line_num = 1;
    for change in diff.iter_all_changes() {
        match change.tag() {
            ChangeTag::Delete => {
                if !diff_only {
                    let mut spans = vec![];
                    if show_line_number { spans.push(Span::raw("    | ")); }
                    spans.push(Span::styled(format!("-{}", change.value()), Style::default().fg(Color::Red)));
                    lines.push(Line::from(spans));
                }
            }
            ChangeTag::Insert => {
                let mut spans = vec![];
                if show_line_number {
                    spans.push(Span::styled(format!("{:>3} | ", line_num), Style::default().fg(Color::Indexed(8))));
                    line_num += 1;
                }
                spans.push(Span::styled(format!("+{}", change.value()), Style::default().fg(Color::Green)));
                lines.push(Line::from(spans));
            }
            ChangeTag::Equal => {
                if !diff_only {
                    let mut spans = vec![];
                    if show_line_number {
                        spans.push(Span::styled(format!("{:>3} | ", line_num), Style::default().fg(Color::Indexed(8))));
                        line_num += 1;
                    }
                    spans.push(Span::raw(format!(" {}", change.value())));
                    lines.push(Line::from(spans));
                } else {
                    line_num += 1;
                }
            }
        }
    }
    Text::from(lines)
}

fn format_word_diff(text: &str, prev_text: &str, show_line_number: bool, diff_only: bool) -> Text<'static> {
    // Simplified word diff
    format_line_diff(text, prev_text, show_line_number, diff_only)
}
